void ApplyRandomForceNugget::create(const Object *primaryObj, const Object *secondaryObj, UnsignedInt lifetimeFrames) const
{
	if (primaryObj == NULL)
		return;
	PhysicsBehavior *physics = (PhysicsBehavior *)primaryObj->m_physics;
	if (physics == NULL)
		return;
	Coord3D force;
	calcRandomForce(m_minForceMagnitude, m_maxForceMagnitude, m_minForcePitch, m_maxForcePitch, &force);
	physics->consume(&force, 0, 0);
}

