const ObjectCreationList *ObjectCreationListStore::findObjectCreationList(const char *name) const
{
	if (OCLCRT::_strcmpi(name, "None") == 0)
		return NULL;

  std::map<NameKeyType, ObjectCreationList *>::const_iterator it = m_lists.find(TheNameKeyGenerator->nameToKey(name));
  if (it == m_lists.end())
	{
		return NULL;
	}
	else
	{
		return (*it).second;
	}
}

// FUNCTION: BFME2 0x001F081A size=94 name=?create@ObjectCreationList@@QAEXPAX000H@Z evidence=N:ledger tier=A
void ObjectCreationList::create(const Object *primaryObj, const Coord3D *primary, const Coord3D *secondary,
	Bool createOwner, UnsignedInt lifetimeFrames)
{
	const ObjectCreationList *ocl = this;
	while (ocl->m_isRetired)
	{
		const ObjectCreationList *current = TheObjectCreationListStore->findObjectCreationList(ocl->m_name.str());
		if (current == NULL)
			break;
		ocl = current;
	}
	for (std::vector<ObjectCreationNugget *>::const_iterator it = ocl->m_nuggets.begin(); it != ocl->m_nuggets.end(); ++it)
		(*it)->create(primaryObj, primary, secondary, createOwner, lifetimeFrames);
}

