void ObjectCreationList::create(void *primaryObj, void *primary, void *secondary, int lifetimeFrames)
{
	const ObjectCreationList *ocl = this;
	while (ocl->m_isRetired)
	{
		const ObjectCreationList *current = TheObjectCreationListStore->findObjectCreationList(ocl->m_name.str());
		if (current == NULL)
			break;
		ocl = current;
	}
	for (std::vector<ObjectCreationNugget *>::const_iterator it = ocl->m_nuggets.begin(); it != ocl->m_nuggets.end(); ++it)
		(*it)->create((const Object *)primaryObj, (const Coord3D *)primary, (const Coord3D *)secondary, lifetimeFrames);
}

