// FUNCTION: BFME2 0x001F0996 size=302 name=??1ObjectCreationListStore@@UAE@XZ evidence=N:ledger tier=A
ObjectCreationListStore::~ObjectCreationListStore()
{
	for (std::vector<ObjectCreationNugget *>::iterator nit = m_allNuggets.begin(); nit != m_allNuggets.end(); ++nit)
	{
		ObjectCreationNugget *nugget = *nit;
		if (nugget != NULL)
			::delete nugget;
	}
	m_allNuggets.clear();

	for (std::map<NameKeyType, ObjectCreationList *>::iterator it = m_lists.begin(); it != m_lists.end(); ++it)
		::delete it->second;
	m_lists.clear();

	for (UnsignedInt i = 0; i < m_retiredLists.size(); ++i)
		::delete m_retiredLists[i];
	m_retiredLists.clear();
}

