// FUNCTION: BFME2 0x001F0C0B size=249 name=?parseObjectCreationListDefinition@ObjectCreationListStore@@SAXPAVINI@@@Z evidence=N:ledger tier=A
void ObjectCreationListStore::parseObjectCreationListDefinition(INI *ini)
{
	const char *name = ini->getNextToken();
	NameKeyType key = TheNameKeyGenerator->nameToKey(name);

	std::map<NameKeyType, ObjectCreationList *>::iterator it = TheObjectCreationListStore->m_lists.find(key);
	if (it != TheObjectCreationListStore->m_lists.end() && ini->getLoadType() == INI_LOAD_RELOAD)
	{
		TheObjectCreationListStore->m_lists.erase(it);
		ObjectCreationList *retired = it->second;
		if (retired != NULL)
		{
			TheObjectCreationListStore->m_retiredLists.push_back(retired);
			retired->m_isRetired = true;
		}
	}

	ObjectCreationList *ocl = new ObjectCreationList(AsciiString(name));
	TheObjectCreationListStore->m_lists[key] = ocl;
	ini->initFromINI(ocl, TheObjectCreationListFieldParse);
}

