Bool GenericObjectCreationNugget::rva001F1513(const Object *obj) const
{
	for (UnsignedInt i = 0; i < m_forbiddenUpgrades.size(); ++i)
	{
		const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgrade(m_forbiddenUpgrades[i]);
		if (upgrade != NULL)
		{
			Int mask = upgrade->getMaskIndex();
			if (obj->hasUpgradeMask(mask) || obj->getControllingPlayer()->testBit(mask))
				return false;
		}
	}

	if (m_requiredUpgrades.size() == 0)
		return true;
	for (UnsignedInt j = 0; j < m_requiredUpgrades.size(); ++j)
	{
		const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgrade(m_requiredUpgrades[j]);
		if (upgrade != NULL)
		{
			Int mask = upgrade->getMaskIndex();
			if (obj->hasUpgradeMask(mask) || obj->getControllingPlayer()->testBit(mask))
				return true;
		}
	}
	return false;
}

