void GenericObjectCreationNugget::parseObject(INI *ini, void *instance, void *store, const void *userData)
{
	// Zero Hour's function-local table: retail emits it after this function's strings, in function order.
	static const FieldParse myFieldParse[] =
	{
		{ "ContainInsideSourceObject", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_containInsideSourceObject) },
		{ "ObjectNames", INI::parseAsciiStringVector, 0, offsetof(GenericObjectCreationNugget, m_names) },
		{ "ObjectCount", INI::parseInt, 0, offsetof(GenericObjectCreationNugget, m_objectCount) },
		{ "InheritsVeterancy", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_inheritsVeterancy) },
		{ "VeterancyLevel", INI::parseInt, 0, offsetof(GenericObjectCreationNugget, m_veterancyLevel) },
		{ "SkipIfSignificantlyAirborne", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_skipIfSignificantlyAirborne) },
		{ "InvulnerableTime", INI::parseDurationUnsignedInt, 0, offsetof(GenericObjectCreationNugget, m_invulnerableTime) },
		{ "StartingBusyTime", INI::parseDurationUnsignedInt, 0, offsetof(GenericObjectCreationNugget, m_startingBusyTime) },
		{ "MinHealth", INI::parsePercentToReal, 0, offsetof(GenericObjectCreationNugget, m_minHealth) },
		{ "MaxHealth", INI::parsePercentToReal, 0, offsetof(GenericObjectCreationNugget, m_maxHealth) },
		{ "RequiresLivePlayer", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_requiresLivePlayer) },
		{ "IgnoreCommandPointLimit", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_ignoreCommandPointLimit) },
		{ "InheritAttributesFromSource", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_inheritAttributesFromSource) },
		{ "UseJustBuiltFlag", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_useJustBuiltFlag) },
		{ "JustBuiltDuration", INI::parseDurationUnsignedInt, 0, offsetof(GenericObjectCreationNugget, m_justBuiltDuration) },
		{ "InheritScriptingName", INI::parseBool, 0, offsetof(GenericObjectCreationNugget, m_inheritScriptingName) },
		{ "WaypointSpawnPoints", INI::parseAsciiString, 0, offsetof(GenericObjectCreationNugget, m_waypointSpawnPoints) },
		{ 0, 0, 0, 0 }
	};
	MultiIniFieldParse p;
	p.add(getCommonFieldParse());
	p.add(myFieldParse);
	GenericObjectCreationNugget *nugget = new GenericObjectCreationNugget;
	nugget->m_requiresObjects = true;
	ini->initFromINIMulti(nugget, p);
	((ObjectCreationList *)instance)->addObjectCreationNugget(nugget);
}

